formal=smooth(vp);emp=smooth(temporal);cc=smooth(cov);fraction=np.clip(np.divide(cc,np.maximum(formal,emp),out=np.zeros_like(cc),where=np.maximum(formal,emp)>0),0,1);fraction[~valid|(neff<1.01)]=0;increment=fraction*np.nan_to_num(contrast);base=np.load(OLD/'arrays/B11_repeatable_all.npz')['source'];np.savez_compressed(OUT/'arrays/R3_red_source.npz',baseline=base,candidate=base+increment,contrast=increment,fraction=fraction,formal_variance=formal,temporal_variance=emp,covariance=cc,effective_count=neff)
