save('R3_red_covariance.json',dict(rows=stats,nuisance_fits=fits,source_sha256=sha(OUT/'arrays/R3_red_source.npz'),common_scene_invariance='R and G receive same latent addition after scale; contrast and temporal variance unchanged, Gbase carries it. Conditional on frozen covariance/calibration, requires actual injection verification.'));print('RED COVARIANCE',stats,flush=True)
